#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>

#define CUDA(call) do { auto error = (call); if (error != cudaSuccess) { \
  std::fprintf(stderr, "%s: %s\n", #call, cudaGetErrorString(error)); std::exit(2); } } while (0)

__device__ __constant__ unsigned short bcodes[16] = {
  0, 0x8000, 0x3f80, 0xbf80, 0x3f00, 0x3f7f, 0x7f7f, 0x0080,
  0x0001, 0x7f80, 0xff80, 0x7fc0, 0x4080, 0xbf01, 0x4f00, 0xcf00};
__device__ __constant__ unsigned gatecodes[16] = {
  0, 0x80000000, 0x3f800000, 0xbf800000, 0x3f000001, 0x3f7fffff,
  0x7f7fffff, 0x00800000, 1, 0x7f800000, 0xff800000, 0x7fc00000,
  0x40800000, 0xbf000001, 0x4f000000, 0xcf000000};

// Original operator expression, compiled independently from table generation.
__device__ __noinline__ float original(float a, float b, float gate) {
  const auto sigmoid = 1.0F / (1.0F + __expf(-a));
  return __fmul_rn((a * sigmoid) * b, gate);
}
__device__ __noinline__ float reference_factor(float a) {
  const auto sigmoid = 1.0F / (1.0F + __expf(-a));
  return a * sigmoid;
}
__global__ void initialize(float *table) {
  const auto i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i < 65536U) {
    const float a = __uint_as_float(i << 16U);
    table[i] = a * (1.0F / (1.0F + __expf(-a)));
  }
}
__global__ void compare(const float *table, unsigned long long *counts) {
  constexpr unsigned cases = 65536U * 16U * 16U;
  for (unsigned i = blockIdx.x * blockDim.x + threadIdx.x; i < cases;
       i += blockDim.x * gridDim.x) {
    const unsigned key = i & 65535U;
    const float a = __uint_as_float(key << 16U);
    const float b = __uint_as_float(unsigned(bcodes[(i >> 16U) & 15U]) << 16U);
    const float gate = __uint_as_float(gatecodes[i >> 20U]);
    const float got = __fmul_rn(__ldg(table + key) * b, gate);
    const float ref = original(a, b, gate);
    if (i < 65536U && __float_as_uint(table[key]) !=
                            __float_as_uint(reference_factor(a)))
      atomicAdd(counts, 1ULL);
    if (__float_as_uint(got) != __float_as_uint(ref)) {
      atomicAdd(counts + 1, 1ULL);
      if (!(isnan(got) && isnan(ref))) atomicAdd(counts + 2, 1ULL);
    }
    if (__bfloat16_as_ushort(__float2bfloat16_rn(got)) !=
        __bfloat16_as_ushort(__float2bfloat16_rn(ref))) {
      const auto prior = atomicAdd(counts + 3, 1ULL);
      if (prior < 8ULL)
        printf("mismatch a=%04x b=%04x gate=%08x ref=%08x got=%08x\n",
               key, unsigned(bcodes[(i >> 16U) & 15U]), gatecodes[i >> 20U],
               __float_as_uint(ref), __float_as_uint(got));
    }
  }
}
int main() {
  float *table = nullptr; unsigned long long *counts = nullptr, host[4]{};
  CUDA(cudaMalloc(&table, 65536U * sizeof(float)));
  CUDA(cudaMalloc(&counts, sizeof(host))); CUDA(cudaMemset(counts, 0, sizeof(host)));
  initialize<<<256,256>>>(table); CUDA(cudaGetLastError());
  compare<<<1024,256>>>(table, counts); CUDA(cudaGetLastError());
  CUDA(cudaMemcpy(host, counts, sizeof(host), cudaMemcpyDeviceToHost));
  std::printf("LUT_PROBE bf16_codes=65536 combinations=16777216 factor_bits_mismatch=%llu f32_bits_mismatch=%llu non_nan_f32_mismatch=%llu bf16_output_mismatch=%llu\n", host[0],host[1],host[2],host[3]);
  CUDA(cudaFree(table)); CUDA(cudaFree(counts));
  return (host[0] || host[1] || host[2] || host[3]) ? 1 : 0;
}
